const features=['Appearance','Intelligence','Lifestyle','Shared values'];
const colors=['#ef7da9','#ddae82','#91c3ac','#8caabd'];
const sliders=features.map((_,i)=>document.getElementById('feature'+i));
function draw(){const vals=sliders.map(input=>Number(input.value)),total=vals.reduce((a,b)=>a+b,0);const bars=document.getElementById('weightbars');bars.replaceChildren();vals.forEach((v,i)=>{document.getElementById('v'+i).textContent=v;const span=document.createElement('span');span.style.background=colors[i];span.style.width=(total?100*v/total:0)+'%';span.title=features[i]+': '+(total?(100*v/total).toFixed(1):'undefined')+'%';bars.append(span)});const leaders=features.filter((_,i)=>vals[i]===Math.max(...vals));document.getElementById('feedback').textContent=!total?'All weights are zero. This model cannot distinguish priorities.':leaders.length===4?'Equal weights. These are arbitrary personal priorities, not a population model.':leaders.join(' and ')+' '+(leaders.length>1?'share the highest weight':'has the highest weight')+' ('+(100*Math.max(...vals)/total).toFixed(1)+'%). This is an arbitrary preference vector, not a score for a person.'}
sliders.forEach(input=>input.addEventListener('input',draw));document.getElementById('reset-weights').addEventListener('click',()=>{sliders.forEach(input=>input.value=25);draw()});draw();
document.querySelectorAll('[data-opt]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-opt]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));document.getElementById('outcome').textContent=button.dataset.opt==='invite'?'Invitation made. The other person may accept or decline freely; no probabilities are known.':button.dataset.opt==='wait'?'You waited. The unchosen invitation remains counterfactual; you cannot know how it would have gone.':'Both outcomes are unknown. Another person always has their own choice.'}));
function match(mode){const shift=mode==='shift'?1:0;document.querySelectorAll('[data-matching]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.matching===mode)));document.querySelectorAll('#match-lines line').forEach((line,i)=>line.setAttribute('y2',35+((i+shift)%5)*55));document.getElementById('matching-status').textContent=Array.from({length:5},(_,i)=>'L'+(i+1)+'–R'+((i+shift)%5+1)).join(', ')+'. Correspondence only; equilibrium is untested.'}document.querySelectorAll('[data-matching]').forEach(button=>button.addEventListener('click',()=>match(button.dataset.matching)));document.getElementById('matching-reset').addEventListener('click',()=>match('rank'));
